int pqcp_channel_epoch_policy_lookup(
	enum pqcp_channel_epoch_condition condition,
	enum pqcp_channel_control_kind control,
	struct pqcp_channel_epoch_policy_decision *decision)
{
	if (condition < PQCP_CHANNEL_EPOCH_CURRENT ||
	    condition >= PQCP_CHANNEL_EPOCH_CONDITION_COUNT ||
	    control < PQCP_CHANNEL_CONTROL_NONE ||
	    control >= PQCP_CHANNEL_CONTROL_KIND_COUNT ||
	    decision == NULL) {
		return -EINVAL;
	}
	*decision = channel_epoch_catalog[condition][control];
	return 0;
}

int pqcp_channel_epoch_policy_catalog_audit(void)
{
	for (size_t condition = 0U;
	     condition < PQCP_CHANNEL_EPOCH_CONDITION_COUNT; ++condition) {
		for (size_t operation = 0U;
		     operation < PQCP_CHANNEL_POLICY_CONTROL_COUNT; ++operation) {
			const struct pqcp_channel_epoch_policy_decision *entry =
				&channel_epoch_catalog[condition][operation];

			if ((size_t)entry->condition != condition ||
			    (size_t)entry->control != operation ||
			    entry->directive >
				PQCP_CHANNEL_EPOCH_TERMINATE ||
			    entry->reason_mask == 0U) {
				return -EBADMSG;
			}
			if (entry->next_state < PQCP_CHANNEL_POLICY_NEW ||
			    entry->next_state > PQCP_CHANNEL_POLICY_TERMINATED) {
				return -EBADMSG;
			}
			if (entry->directive ==
				    PQCP_CHANNEL_EPOCH_DENY &&
			    entry->error == 0) {
				return -EBADMSG;
			}
		}
	}
	return 0;
}
